diff --git a/src/git/gitEnvironment.ts b/src/git/gitEnvironment.ts
new file mode 100644
--- /dev/null
+++ b/src/git/gitEnvironment.ts
@@ -0,0 +1,32 @@
+// 매 호출의 실제 Git 환경은 새로 읽되, 관계없는 환경 값까지 복사하지 않는 접근 경계다.
+
+/**
+ * object spread와 같은 호출별 override 우선순위를 적용해 값 하나만 읽는다.
+ * @param name 조회할 환경 변수 이름 @param overrides Native 명령의 own enumerable 환경 값
+ * @returns 명시한 빈 값/undefined도 보존한다. 상속/비열거 속성은 override로 취급하지 않는다.
+ */
+export function gitEnvironmentValue(name: string, overrides?: Readonly<Record<string, string>>): string | undefined {
+  return overrides && Object.prototype.propertyIsEnumerable.call(overrides, name) ? overrides[name] : process.env[name];
+}
+
+/**
+ * 기존 설정 슬롯 순회의 상한을 구하되 전체 환경 값은 만들지 않는다.
+ * @param overrides 명령별 환경. 중복 키는 병합 후 한 키로 계산한다.
+ * @returns 기존 Math.min(병합한 키 수, GIT_CONFIG_COUNT)와 같은 값. 잘못된 설정은 Native Git에 그대로 전달한다.
+ */
+export function gitConfigurationEnvironmentLimit(overrides?: Readonly<Record<string, string>>): number {
+  const count = Number(gitEnvironmentValue("GIT_CONFIG_COUNT", overrides) ?? 0);
+  if (!(count > 0)) return count;
+  const keys = new Set(Object.keys(process.env));
+  if (overrides) for (const name of Object.keys(overrides)) keys.add(name);
+  return Math.min(keys.size, count);
+}
+
+/**
+ * 복구 경로의 실행 문맥에 필요한 GIT_* 이름과 값만 현재 환경에서 새로 복사한다.
+ * @returns 이름 순서가 안정적인 독립 배열. 전역 캐시를 만들지 않아 중간의 변수 추가·변경·삭제도 확인한다.
+ */
+export function snapshotGitEnvironment(): [string, string | undefined][] {
+  return Object.keys(process.env).filter(name => name.startsWith("GIT_"))
+    .sort((left, right) => left.localeCompare(right)).map(name => [name, process.env[name]]);
+}
diff --git a/test/gitEnvironment.test.ts b/test/gitEnvironment.test.ts
