+++ b/test/gitEnvironment.test.ts
@@ -0,0 +1,50 @@
+import assert from "node:assert/strict";
+import test, { type TestContext } from "node:test";
+import { gitConfigurationEnvironmentLimit, gitEnvironmentValue, snapshotGitEnvironment } from "../src/git/gitEnvironment";
+
+/** 테스트 worker의 환경 값만 바꾸고 종료 때 원래 값/부재를 복원한다. */
+function environment(t: TestContext, values: Record<string,string|undefined>) {
+  const previous = Object.fromEntries(Object.keys(values).map(name => [name,process.env[name]]));
+  for(const [name,value] of Object.entries(values))if(value===undefined)delete process.env[name];else process.env[name]=value;
+  t.after(()=>{for(const [name,value] of Object.entries(previous))if(value===undefined)delete process.env[name];else process.env[name]=value;});
+}
+
+test("Git environment lookup preserves enumerable override precedence and explicit empty values",t=>{
+  environment(t,{GSC_ENVIRONMENT_VALUE:"inherited"});
+  assert.equal(gitEnvironmentValue("GSC_ENVIRONMENT_VALUE"),"inherited");
+  assert.equal(gitEnvironmentValue("GSC_ENVIRONMENT_VALUE",{GSC_ENVIRONMENT_VALUE:""}),"");
+  assert.equal(gitEnvironmentValue("GSC_ENVIRONMENT_VALUE",{GSC_ENVIRONMENT_VALUE:undefined} as any),undefined);
+  const overrides=Object.create({GSC_ENVIRONMENT_VALUE:"prototype"});
+  Object.defineProperty(overrides,"GSC_ENVIRONMENT_VALUE",{value:"hidden",enumerable:false});
+  assert.equal(gitEnvironmentValue("GSC_ENVIRONMENT_VALUE",overrides),"inherited");
+});
+
+test("Git configuration slot bounds preserve malformed-count handling and merged key counts",t=>{
+  environment(t,{GIT_CONFIG_COUNT:undefined});
+  for(const count of [undefined,"","0","1","1.5","-1","not-a-count","999999","Infinity"]){
+    const overrides={GIT_CONFIG_COUNT:count,GIT_CONFIG_KEY_0:"core.fsmonitor",GIT_CONFIG_VALUE_0:"false"} as any;
+    const previous={...process.env,...overrides};
+    assert.equal(gitConfigurationEnvironmentLimit(overrides),Math.min(Object.keys(previous).length,Number(previous.GIT_CONFIG_COUNT??0)));
+  }
+});
+
+test("configuration lookup never reads unrelated caller environment values",t=>{
+  environment(t,{GIT_CONFIG_COUNT:undefined});
+  const overrides={GIT_CONFIG_COUNT:"2",GIT_CONFIG_KEY_0:"core.fsmonitor",GIT_CONFIG_VALUE_0:"false"};
+  Object.defineProperty(overrides,"UNRELATED_SECRET",{enumerable:true,get(){throw new Error("Unrelated environment must not be read");}});
+  assert.equal(gitConfigurationEnvironmentLimit(overrides),2);
+  assert.equal(gitEnvironmentValue("GIT_CONFIG_VALUE_0",overrides),"false");
+});
+
+test("Git identity snapshots stay fresh across added, changed and deleted variables",t=>{
+  environment(t,{GIT_GSC_ENVIRONMENT_A:"first",GIT_GSC_ENVIRONMENT_B:undefined});
+  const first=snapshotGitEnvironment();
+  assert.deepEqual(first,Object.entries(process.env).filter(([name])=>name.startsWith("GIT_")).sort(([a],[b])=>a.localeCompare(b)));
+  process.env.GIT_GSC_ENVIRONMENT_A="second";process.env.GIT_GSC_ENVIRONMENT_B="added";
+  const next=snapshotGitEnvironment();
+  assert.equal(new Map(first).get("GIT_GSC_ENVIRONMENT_A"),"first");
+  assert.equal(new Map(next).get("GIT_GSC_ENVIRONMENT_A"),"second");
+  assert.equal(new Map(next).get("GIT_GSC_ENVIRONMENT_B"),"added");
+  delete process.env.GIT_GSC_ENVIRONMENT_A;
+  assert.equal(new Map(snapshotGitEnvironment()).has("GIT_GSC_ENVIRONMENT_A"),false);
+});
